/**
 * Two made-up HEIC photos for tests, generated by a script and never taken by any camera. They hold
 * no person, document or place: only flat colours.
 *
 * - SMALL (64 x 48): four flat quarters, red top left, green top right, blue bottom left, white
 *   bottom right, with a made-up camera name ("MadeUpCam") in its EXIF data so a test can show
 *   the converted copy carries none of it.
 * - LARGE (1200 x 1000): one flat grey, used to show the pixel budget refuses a photo before
 *   decoding it.
 *
 * Made with pillow-heif 1.8.1 (libheif 1.23.6 with the x265 encoder): Image.new() filled with the
 * colours above, then Image.save(format='HEIF'). Kept as text so the repository holds no binary.
 */

function decode(lines: readonly string[]): Uint8Array {
  return new Uint8Array(Buffer.from(lines.join(''), 'base64'));
}

